from pydantic import BaseModel, Field

class Paper(BaseModel):
    """One provided paper: its own title and which OTHER provided papers it references."""
    title: str | None = Field(description="This paper's title")
    references_provided_papers: list[str] = Field(
        description="Titles of the OTHER provided papers (from the known collection) that appear in this paper's reference list"
    )

class Parse(BaseModel):
    papers: list[Paper]
